      add(head, torus(H.r.x * 1.13, 0.028, 10, 30), acc, [H.c.x, H.c.y + 0.044, H.c.z - 0.005], [PI / 2 - 0.2, 0, 0], [1, H.r.z / H.r.x, 1]);
      const b = joint(head, 'pom', [H.c.x, H.c.y + H.r.y * 1.2 + 0.02, H.c.z - 0.02]);
      add(b, sphere(0.04, 14, 10), topAcc, [0, 0.03, 0]);
