      const a = add(head, capsule(0.0045, 0.1, 3, 6), frame, [(p.x + arm.p.x) / 2, (p.y + arm.p.y) / 2 + 0.005, (p.z + arm.p.z) / 2], null, null, { noShadow: true });
      a.quaternion.setFromUnitVectors(new T.Vector3(0, 1, 0), arm.p.clone().sub(p).normalize());
